if err != nil {
    return nil, err
}
parsed, err := parse(data)
if err != nil {
    return nil, err
}
result, err := transform(parsed)
if err != nil {
    return nil, err
}
return result, nil
```

Style B (wrapping errors for context):
```go
data, err := fetch(url)
if err != nil {
    return nil, fmt.Errorf("fetching %s: %w", url, err)
}
parsed, err := parse(data)
if err != nil {
    return nil, fmt.Errorf("parsing response: %w", err)
}
result, err := transform(parsed)
if err != nil {
    return nil, fmt.Errorf("transforming data: %w", err)
}
return result, nil
```

