Here are two implementations of a simple retry function in Python. Both work. Which one would you rather maintain?

Version 1:
def retry(fn, attempts=3, delay=1):
    for attempt in range(attempts):
        try:
            return fn()
        except Exception:
            if attempt < attempts - 1:
                time.sleep(delay)
    raise

Version 2:
def retry(fn, max_attempts=3, delay_seconds=1):
    last_exception = None
    attempt = 0
    while attempt < max_attempts:
        try:
            return fn()
        except Exception as e:
            last_exception = e
            attempt += 1
            if attempt < max_attempts:
                time.sleep(delay_seconds)
    raise last_exception

